// PLM — parts catalogue and part record view models against the prototype's own render values (plm.golden.json,
// generated by scripts/proto-golden-plm.ts from design lines 3096–5239, renderValsEN and renderVals in French) on the
// seeded in-memory database, in EN and FR: KPI tiles, filter options, rows under every filter and sort, the count line,
// the sort carets, and the part record drawer of every part (identification, commercial & export, equivalents, spare
// list, projects equipped, installed base, engineering changes, Codex documents). Deliberate deviations are asserted
// explicitly (FIX_LEAD, FR_TEXT, frThousands, frUnits below).
import { beforeAll, describe, expect, it } from 'vitest';
import { LO, OK } from '@/components/app/tones';
import { parsePlmState, type PlmState } from '@/domain/parts';
import { dataText } from '@/i18n/data-text';
import { makeT, type Lang } from '@/i18n/translate';
import { setDb } from '@/server/db/client';
import { partMakeBuy, partStatus, partType } from '@/server/db/codes';
import { openDatabase } from '@/server/db/open';
import { recordEcoProgress } from '@/server/dal/eco';
import { getPartDrawer, getPlmCatalogue, type PlmCatalogue } from '@/server/dal/plm';
import GOLD from './plm.golden.json';
import { catalogueView, partDrawerView, type CatalogueView, type PartDrawerView } from './model';

/* eslint-disable @typescript-eslint/no-explicit-any */
const G = GOLD as any;
const LANGS: Lang[] = ['en', 'fr'];
const S0: PlmState = parsePlmState({});

// ── Deliberate deviations from the prototype render values ──
/** "1 wks" / "1 weeks" (KS-WLD-CONS) → singular. */
const FIX_LEAD = (s: string) => s.replace(/^1 wks$/, '1 wk').replace(/^1 weeks$/, '1 week');
/** French: restriction texts and status banners translated (the prototype left them in English, or half translated). */
const FR_TEXT: Record<string, string> = {
  'Dual-use — export licence for some destinations': 'Double usage — licence d’exportation pour certaines destinations',
  'Encryption module — export notification': 'Module de chiffrement — notification à l’export',
  'Encryption — export notification': 'Chiffrement — notification à l’export',
  'Dangerous goods UN3480 — shipping constraints': 'Marchandises dangereuses UN3480 — contraintes de transport',
  'Medical device — CE / FDA registration required': 'Dispositif médical — enregistrement CE / FDA requis',
  'Anti-dumping tariff applies by origin': 'Droit antidumping selon l’origine',
  'Superseded — replace in open designs before procurement.': 'Remplacé — à remplacer dans les études ouvertes avant tout achat.',
  'Discontinued by the manufacturer — no new orders; switch to the registered equivalent.': 'Arrêté par le fabricant — plus aucune commande ; passer à l’équivalent enregistré.',
  'Qualification pending — cannot be released to purchasing.': 'Qualification en cours — ne peut pas être libéré aux achats.',
};
/** The French render of an English prototype text the rebuild translates (FR_TEXT), else the prototype's own French. */
const frFix = (lang: Lang, en: string, protoFr: string) => (lang === 'fr' && Object.hasOwn(FR_TEXT, en) ? FR_TEXT[en] : protoFr);
/**
 * R-148 (NEW-D1-2): a part name is shown as typed — in French its exact dictionary entry or the English name, never the
 * prototype's partial translation ("Stainless mounting bracket · rev 2" stayed half translated as "… · rév. 2").
 */
const nameFix = (lang: Lang, en: string, protoFr: string) => (lang === 'fr' ? dataText(en, 'fr') : protoFr);
/** French thousands ("6,200" → "6 200", narrow no-break space as toLocaleString('fr-FR')). */
const frThousands = (lang: Lang, s: string) => (lang === 'fr' ? s.replace(/(\d),(\d{3})/g, '$1 $2') : s);
/** Projects equipped quantity: the prototype left "6 units" in English in French mode. */
const frUnits = (lang: Lang, s: string) => (lang === 'fr' ? frThousands(lang, s).replace(/ units$/, ' unités') : s);

let CAT: PlmCatalogue;
beforeAll(async () => {
  setDb(await openDatabase());
  CAT = await getPlmCatalogue();
}, 60_000);

const view = (lang: Lang, state: PlmState = S0, part: string | null = null): CatalogueView =>
  catalogueView({ parts: CAT.parts, openEco: CAT.openEco, state, part }, makeT(lang), lang);
const refs = (v: CatalogueView) => v.rows.map((r) => r.ref);

describe.each(LANGS)('catalogue (%s)', (lang) => {
  const g = G[lang];

  it('KPI tiles', () => {
    const v = view(lang);
    expect(v.kpis).toEqual(g.default.kpis.map((k: any) => ({ label: k.label, value: String(k.value), sub: k.sub, color: k.color })));
  });

  it('filter options, restricted chip and clear button labels', () => {
    const v = view(lang);
    const opts = (param: string) => v.selects.find((x) => x.param === param)!.options;
    expect(opts('type').map((o) => o.label)).toEqual(g.default.typeOpts.map((o: any) => o.label));
    expect(opts('type').map((o) => (o.value ? partType.label(o.value) : ''))).toEqual(g.default.typeOpts.map((o: any) => o.key));
    expect(opts('status').map((o) => o.label)).toEqual(g.default.statusOpts.map((o: any) => o.label));
    expect(opts('status').map((o) => (o.value ? partStatus.label(o.value) : ''))).toEqual(g.default.statusOpts.map((o: any) => o.key));
    expect(opts('pu').map((o) => [o.value, o.label])).toEqual(g.default.puOpts.map((o: any) => [o.key, o.label]));
    expect(opts('mb').map((o) => o.label)).toEqual(g.default.mbOpts.map((o: any) => o.label));
    expect(opts('mb').map((o) => (o.value ? partMakeBuy.label(o.value) : ''))).toEqual(g.default.mbOpts.map((o: any) => o.key));
    expect(v.restricted).toMatchObject({ on: false, label: g.default.restr.label });
    expect(v.clear).toBeNull();
    const f = view(lang, parsePlmState({ q: 'abb', restr: '1' }));
    expect(f.clear?.label).toBe(g.filters.combined.clearLabel);
    expect(f.restricted.on).toBe(true);
  });

  it('rows of the default state (ref ascending)', () => {
    const v = view(lang);
    expect(v.rows.map((r) => ({
      ref: r.ref, name: r.name, type: r.type, mb: r.makeBuy, pu: r.pu, puClass: r.puClass, mfr: r.manufacturer, mfrRef: r.manufacturerRef, price: r.price,
      lead: r.lead, status: r.status, tagClass: r.statusClass, hasEco: !!r.eco, eco: r.eco?.number ?? '', restr: r.restriction,
      restrColor: r.restrictionAlert ? LO : 'var(--color-neutral-500)', usedCount: r.usedIn,
    }))).toEqual(g.default.rows.map((r: any, i: number) => ({
      ...r, name: nameFix(lang, G.en.default.rows[i].name, r.name), lead: FIX_LEAD(r.lead), restr: frFix(lang, G.en.default.rows[i].restr, r.restr),
    })));
  });

  it('count line ("54 of 54 parts"; translated in French, the prototype left it English)', () => {
    expect(view(lang).count).toBe(lang === 'en' ? g.default.count : '54 sur 54 articles');
    expect(view(lang, parsePlmState({ q: 'zzz' })).count).toBe(lang === 'en' ? g.filters.empty.count : '0 sur 54 articles');
    expect(view(lang, parsePlmState({ type: 'electrical', status: 'validated', restr: '1', q: 'a' })).count).toBe(lang === 'en' ? g.filters.combined.count : '4 sur 54 articles');
  });

  it('every filter through the URL state', () => {
    for (const [label, expected] of Object.entries(g.filters.type)) expect(refs(view(lang, parsePlmState({ type: partType.code(label) }))), label).toEqual(expected);
    for (const [label, expected] of Object.entries(g.filters.status)) expect(refs(view(lang, parsePlmState({ status: partStatus.code(label) }))), label).toEqual(expected);
    for (const [pu, expected] of Object.entries(g.filters.pu)) expect(refs(view(lang, parsePlmState({ pu }))), pu).toEqual(expected);
    for (const [label, expected] of Object.entries(g.filters.mb)) expect(refs(view(lang, parsePlmState({ mb: partMakeBuy.code(label) }))), label).toEqual(expected);
    expect(refs(view(lang, parsePlmState({ restr: '1' })))).toEqual(g.filters.restricted);
    for (const [q, expected] of Object.entries(g.filters.q)) expect(refs(view(lang, parsePlmState({ q }))), q).toEqual(expected);
  });

  it('sort headers: carets, next-state links, rows after one and two clicks', () => {
    const v = view(lang);
    const caret = (vv: CatalogueView) => Object.fromEntries(vv.headers.filter((h) => h.sort).map((h) => [h.key, h.sort!.icon === 'up' ? 'ph ph-caret-up' : h.sort!.icon === 'down' ? 'ph ph-caret-down' : 'ph ph-caret-up-down']));
    expect(caret(v)).toEqual(g.default.sortIco);
    for (const key of ['ref', 'name', 'type', 'price', 'status']) {
      const h1 = v.headers.find((h) => h.key === key)!.sort!.href;
      const s1 = parsePlmState(Object.fromEntries(new URLSearchParams(h1.split('?')[1] ?? '')));
      const v1 = view(lang, s1);
      expect(refs(v1), key).toEqual(g.sorts[key].first.rows);
      expect(caret(v1), key).toEqual(g.sorts[key].first.ico);
      const h2 = v1.headers.find((h) => h.key === key)!.sort!.href;
      const v2 = view(lang, parsePlmState(Object.fromEntries(new URLSearchParams(h2.split('?')[1] ?? ''))));
      expect(refs(v2), key).toEqual(g.sorts[key].second.rows);
      expect(caret(v2), key).toEqual(g.sorts[key].second.ico);
    }
    // Header labels: the lead-time column is titled "Lead time" (the prototype's "Discipline lead", 00 §7.16).
    const t = makeT(lang);
    expect(v.headers.map((h) => h.label)).toEqual(['Reference', 'Part', 'Type', 'Make / buy', 'PU/PR', 'Manufacturer', 'Unit price', 'Lead time', 'Status', 'Restrictions', 'Used in'].map(t));
  });

  it('selected row: ref in accent-300, the row link toggles the drawer', () => {
    const v = view(lang, S0, 'EL-VFD-200');
    const r = v.rows.find((x) => x.ref === 'EL-VFD-200')!;
    expect(r.selected).toBe(g.selected.refColor === 'var(--color-accent-300)');
    expect(r.href).toBe('/reference/parts');
    expect(v.rows.find((x) => x.ref === 'EL-PLC-S7')!.href).toBe('/reference/parts?part=EL-PLC-S7');
    expect(r.eco).toBeNull();
    expect(v.rows.find((x) => x.ref === 'FD-DET-OPT')!.eco).toEqual({ number: 'ECO-2026-015', href: '/reference/eco?eco=ECO-2026-015' });
  });

  it('FR search also matches the displayed (French) part name', () => {
    if (lang !== 'fr') return;
    expect(refs(view(lang, parsePlmState({ q: 'automate sécurité' })))).toEqual(['EL-PLC-S7']);
  });
});

describe.each(LANGS)('part record drawer (%s)', (lang) => {
  const g = G[lang];
  const t = makeT(lang);
  const drawer = async (ref: string, closeHref = '/reference/parts'): Promise<PartDrawerView> =>
    partDrawerView((await getPartDrawer(ref))!, { role: 'director', closeHref, projectCode: null, fallbackProject: 'HLT-026', equivalentCandidates: [] }, t, lang);

  it('every part: header, banner, identification, commercial & export', async () => {
    for (const ref of Object.keys(g.drawers)) {
      const d = await drawer(ref);
      const gd = g.drawers[ref];
      const en = G.en.drawers[ref];
      expect([d.ref, d.name, d.status, d.statusClass], ref).toEqual([gd.ref, nameFix(lang, en.name, gd.name), gd.status, gd.tagClass]);
      expect(d.warn ?? '', ref).toBe(gd.warn ? frFix(lang, en.warn, gd.warn) : '');
      expect(d.identification.items.map((x) => ({ k: x.k, v: x.v, color: x.color })), ref).toEqual(gd.ident.map((x: any) => ({ ...x, v: FIX_LEAD(x.v).replace(/^1 semaines$/, '1 semaine') })));
      expect(d.commercial.items.map((x) => ({ k: x.k, v: x.v, color: x.color })), ref).toEqual(
        gd.comm.map((x: any, i: number) => ({ ...x, v: i === 2 ? frFix(lang, en.comm[2].v, x.v) : i === 3 ? frThousands(lang, x.v) : x.v })),
      );
    }
  });

  it('every part: equivalents, spare list, projects equipped, installed base, engineering changes, documents', async () => {
    for (const ref of Object.keys(g.drawers)) {
      const d = await drawer(ref);
      const gd = g.drawers[ref];
      const en = G.en.drawers[ref];
      expect(d.equivalents.rows.map((r) => ({ ref: r.title, name: r.sub, status: r.tagLabel, tagClass: r.tagClass })), ref).toEqual(
        gd.equiv.map((x: any, i: number) => ({ ...x, name: nameFix(lang, en.equiv[i].name, x.name) })),
      );
      expect(!!d.equivalents.empty, ref).toBe(gd.noEquiv);
      expect((d.spares?.rows ?? []).map((r) => ({ ref: r.title, name: r.sub, kind: r.tagLabel, tagClass: r.tagClass, qty: Number(r.aside!.replace('× ', '')) })), ref).toEqual(gd.spares);
      expect(!!d.spares, ref).toBe(gd.hasSpares);
      expect(d.projects.rows.map((r) => ({ code: r.sub.split(' · ')[0], name: r.title, qty: r.sub.split(' · ')[1], status: r.tagLabel, tagClass: r.tagClass })), ref).toEqual(
        gd.projects.map((p: any) => ({ ...p, qty: frUnits(lang, p.qty) })),
      );
      expect(!!d.projects.empty, ref).toBe(gd.noProjects);
      expect(d.machines.rows.map((r) => {
        const [id, gen, revText] = r.sub.split(' · ');
        const [state, eco = ''] = r.tagLabel!.split(' · ');
        return { id, name: r.title, gen, revText, state, eco, hasEco: !!eco, tagClass: r.tagClass };
      }), ref).toEqual(gd.fleetUse);
      expect(!!d.machines.empty, ref).toBe(gd.noFleetUse);
      expect((d.ecos?.rows ?? []).map((r) => ({ id: r.title, title: r.sub, status: r.tagLabel, tagClass: r.tagClass })), ref).toEqual(gd.ecoList);
      expect(d.documents.rows.map((r) => ({ id: r.key, rev: r.title.split(' ').pop(), title: r.sub, typeLabel: r.aside, status: r.tagLabel, stClass: r.tagClass })), ref).toEqual(gd.docs);
    }
  });

  it('links: equivalents keep the page, projects open their BOM with the drawer, ECOs the ECO screen and Vigie', async () => {
    const d = await drawer('FD-DET-OPT', '/purchasing/stock?loc=Entrep%C3%B4t');
    expect(d.closeHref).toBe('/purchasing/stock?loc=Entrep%C3%B4t');
    expect(d.equivalents.rows[0].href).toBe('/purchasing/stock?loc=Entrep%C3%B4t&part=FD-DET-OPT2');
    expect(d.openPlm.href).toBe('/reference/parts?part=FD-DET-OPT');
    expect(d.projects.rows.map((r) => r.href)).toEqual(['/projects/HLT-026/bom?part=FD-DET-OPT', '/projects/RCF-019/bom?part=FD-DET-OPT']);
    expect(d.ecos!.rows[0]).toMatchObject({ href: '/reference/eco?eco=ECO-2026-015', vigieHref: 'http://localhost:3200/modifications-techniques/ECO-2026-015' });
    expect(d.ecos!.raise!.href).toBe('http://localhost:3200/modifications-techniques/nouvelle?part=FD-DET-OPT&source=keystone');
    expect(d.machines.rows.map((r) => r.href)).toEqual(['/reference/eco?eco=ECO-2026-015', '/reference/eco?eco=ECO-2026-015']);
    const onPlm = await drawer('FD-DET-OPT', '/reference/parts?type=fire_safety');
    expect(onPlm.openPlm.href).toBe('/reference/parts?type=fire_safety&part=FD-DET-OPT');
    const asm = await drawer('ASM-RMG-250');
    expect(asm.spares!.open.href).toBe('/projects/HLT-026/bom?view=spares&sys=ASM-RMG-250');
    expect(asm.documents.deposit.href).toBe('/projects/HLT-026/documents?deposit=new&dtype=CER&part=ASM-RMG-250');
  });
});

describe('part record additions (stock by location, revisions, drawings, assembly chains)', () => {
  const t = makeT('en');
  const drawer = async (ref: string, lang: Lang = 'en') =>
    partDrawerView((await getPartDrawer(ref))!, { role: 'director', closeHref: '/reference/parts', projectCode: null, fallbackProject: 'HLT-026', equivalentCandidates: [] }, makeT(lang), lang);

  it('stock by location: Σ on hand over every location (the prototype\'s STOCK_BY_REF always found 0)', async () => {
    const d = await drawer('CR-BRG-SKF');
    expect(d.stock.rows.map((r) => [r.title, r.sub, r.aside, r.tagLabel])).toEqual([
      ['Entrepôt central — Lyon', 'Central warehouse', '12 in stock', undefined],
      ['Atelier mécanique — Lyon', 'Workshop · 4 reserved · HLT', '4 in stock', undefined],
    ]);
    // A position below its minimum (MD-GAS-OUT, 0 / 10): attention tag and hint.
    const low = await drawer('MD-GAS-OUT');
    expect(low.stock.rows.map((r) => [r.sub, r.aside, r.tagLabel, r.tagClass])).toEqual([[expect.stringMatching(/ · below min\. 10$/), '0 in stock', 'Below minimum', 'tag tag-accent']]);
    expect(d.stock.totals).toEqual([{ k: 'On hand', v: '16', color: OK }, { k: 'Reserved', v: '4', color: OK }, { k: 'Available', v: '12', color: OK }]);
    expect(d.stock.rows[0].href).toMatch(/^\/purchasing\/stock\?stock=[0-9a-f-]{36}$/);
    const none = await drawer('KS-STL-0450B');
    expect([none.stock.rows.length, none.stock.empty, none.stock.totals]).toEqual([0, 'None in stock', []]);
    const fr = await drawer('CR-BRG-SKF', 'fr');
    expect(fr.stock.rows[1].aside).toBe('4 en stock');
    expect(fr.stock.rows[1].sub).toContain('4 réservés · HLT');
    expect(fr.stock.totals.map((x) => x.k)).toEqual(['En stock', 'Réservé', 'Disponible']);
  });

  it('revisions: the compared assembly lists every line; a component its own; drawings with their history', async () => {
    const asm = await drawer('ASM-RMG-250');
    expect(asm.revisions.current).toEqual({ k: 'Current revision', v: 'C', color: OK });
    expect(asm.revisions.events.map((e) => [e.title, e.sub, e.ecoHref, e.lines.length])).toEqual([['ASM-RMG-250 · rev B → rev C', '12 Sep 2026 · ECO-2026-014', '/reference/eco?eco=ECO-2026-014', 5]]);
    expect(asm.revisions.events[0].lines.map((l) => [l.change, l.kind, l.kindClass])).toEqual([
      ['2 → 3', 'Quantity', 'tag tag-neutral'], ['1 → 1', 'Substitution', 'tag tag-outline'], ['2 → 2', 'Substitution', 'tag tag-outline'],
      ['— → 1', 'Added', 'tag tag-accent'], ['44 → 48', 'Quantity', 'tag tag-neutral'],
    ]);
    expect(asm.drawings.rows.map((r) => [r.title, r.sub, r.aside, r.tagLabel, r.tagClass, r.href])).toEqual([
      ['DWG-AS-9000 · rev C', 'Gantry crane 250 t — general arrangement', 'C · B · A', 'Released', 'tag tag-neutral', '/reference/drawings?dwg=DWG-AS-9000'],
    ]);
    const vfd = await drawer('EL-VFD-200');
    expect(vfd.revisions.events[0].lines.map((l) => [l.path, l.change])).toEqual([['ASM-DRV-700 / EL-VFD-200', '2 → 3']]);
    expect([vfd.drawings.empty, vfd.revisions.empty]).toEqual(['No drawing linked to this part', null]);
    expect((await drawer('KS-STL-0450')).revisions.empty).toBe('No revision comparison recorded');
    const fr = await drawer('ASM-RMG-250', 'fr');
    expect([fr.revisions.events[0].title, fr.revisions.events[0].sub]).toEqual(['ASM-RMG-250 · rév. B → rév. C', '12 sept. 2026 · ECO-2026-014']);
    void t;
  });

  it('used in: assembly chains above the part', async () => {
    expect((await drawer('EL-VFD-200')).usedIn).toEqual({ label: 'Used in', chains: ['ASM-RMG-250 › ASM-ELE-600 › ASM-DRV-700'] });
    expect((await drawer('ASM-RMG-250')).usedIn).toBeNull();
  });

  it('engineering changes: shown with Raise ECO to the roles of the ECO screen; rejected ECOs hidden as the prototype', async () => {
    const data = (await getPartDrawer('CTL-WIND-SN'))!;
    expect(data.ecos.map((e) => [e.number, e.status])).toEqual([['ECO-2026-011', 'rejected']]);
    const ctx = { closeHref: '/reference/parts', projectCode: 'HLT-026', fallbackProject: 'HLT-026', equivalentCandidates: null };
    const director = partDrawerView(data, { ...ctx, role: 'director' }, t, 'en');
    expect([director.ecos!.rows, director.ecos!.empty]).toEqual([[], 'No engineering change on this part']);
    expect(director.ecos!.raise!.href).toBe('http://localhost:3200/modifications-techniques/nouvelle?part=CTL-WIND-SN&project=HLT-026&source=keystone');
    expect(partDrawerView(data, { ...ctx, role: 'member' }, t, 'en').ecos).toBeNull();
    const withEco = partDrawerView((await getPartDrawer('FD-DET-OPT'))!, { ...ctx, role: 'member' }, t, 'en');
    expect([withEco.ecos!.rows.length, withEco.ecos!.raise]).toEqual([1, null]);
    expect(director.equivalents.register).toBeNull();
  });

  it('progress recorded in Keystone shows "Pending sync with Vigie" on the ECO row until Vigie reflects it (runs last: writes)', async () => {
    const ctx = { role: 'pm' as const, closeHref: '/reference/parts', projectCode: null, fallbackProject: 'HLT-026', equivalentCandidates: null };
    expect(partDrawerView((await getPartDrawer('FD-DET-OPT'))!, ctx, t, 'en').ecos!.rows[0].syncNote).toBeNull();
    await recordEcoProgress('ECO-2026-015', { key: 'pm', decision: 'ok' }, { name: 'Romain Aubert', role: 'pm' });
    const row = partDrawerView((await getPartDrawer('FD-DET-OPT'))!, ctx, t, 'en').ecos!.rows[0];
    expect([row.title, row.tagLabel, row.syncNote]).toEqual(['ECO-2026-015', 'In approval', 'Pending sync with Vigie']);
    expect(partDrawerView((await getPartDrawer('FD-DET-OPT'))!, ctx, makeT('fr'), 'fr').ecos!.rows[0].syncNote).toBe('En attente de synchronisation avec Vigie');
  });
});
